	const workspace = args.workspace ?? `${new URL(args.url).hostname.replace(/[^a-zA-Z0-9-]/g, "-")}_shannon-${Date.now()}`;
	const workspacePath = path.join(workspacesDir, workspace);
	const internalPath = path.join(workspacePath, INTERNAL_DIR);
	fs.mkdirSync(workspacePath, { recursive: true });
	fs.chmodSync(workspacePath, 511);
	migrateLegacyWorkspaceLayout(workspacePath);
	fs.mkdirSync(internalPath, { recursive: true });
	fs.chmodSync(internalPath, 511);
	for (const dir of [
		"deliverables",
		"scratchpad",
		".playwright-cli",
		".playwright"
	]) {
		const dirPath = path.join(internalPath, dir);
		fs.mkdirSync(dirPath, { recursive: true });
		fs.chmodSync(dirPath, 511);
	}
	const shannonDir = path.join(repo.hostPath, ".shannon");
	for (const dir of [
		"deliverables",
		"scratchpad",
		".playwright-cli"
	]) fs.mkdirSync(path.join(shannonDir, dir), { recursive: true });
	fs.mkdirSync(path.join(repo.hostPath, ".playwright"), { recursive: true });
