function parseStartArgs(argv) {
	let url = "";
	let repo = "";
	let config;
	let workspace;
	let output;
	let pipelineTesting = false;
	let debug = false;
	for (let i = 0; i < argv.length; i++) {
		const arg = argv[i];
		const next = argv[i + 1];
		switch (arg) {
			case "-u":
			case "--url":
				if (next && !next.startsWith("-")) {
					url = next;
					i++;
				}
				break;
			case "-r":
			case "--repo":
				if (next && !next.startsWith("-")) {
					repo = next;
					i++;
				}
				break;
			case "-c":
			case "--config":
				if (next && !next.startsWith("-")) {
					config = next;
					i++;
				}
				break;
			case "-w":
			case "--workspace":
				if (next && !next.startsWith("-")) {
					workspace = next;
					i++;
				}
				break;
			case "-o":
			case "--output":
				if (next && !next.startsWith("-")) {
					output = next;
					i++;
				}
				break;
			case "--pipeline-testing":
				pipelineTesting = true;
				break;
			case "--debug":
				debug = true;
				break;
			default:
				console.error(`Unknown option: ${arg}`);
				console.error(`Run "${getMode() === "local" ? "./shannon" : "npx @keygraph/shannon"} help" for usage`);
				process.exit(1);
		}
	}
	if (!url || !repo) {
		console.error("ERROR: --url and --repo are required");
		console.error(`Usage: ${getMode() === "local" ? "./shannon" : "npx @keygraph/shannon"} start -u <url> -r <path>`);
		process.exit(1);
	}
	return {
		url,
		repo,
		pipelineTesting,
		debug,
		...config && { config },
		...workspace && { workspace },
		...output && { output }
	};
}
blockSudo();
const args = process.argv.slice(2);
const command = args[0];
switch (command) {
	case "start":
		await start({
			...parseStartArgs(args.slice(1)),
			version: getVersion()
		});
		break;
	case "stop":
		stop(args.includes("--clean"), args.includes("--yes") || args.includes("-y"));
		break;
	case "logs": {
		const workspaceId = args[1];
		if (!workspaceId) {
			console.error("ERROR: Workspace ID is required");
			console.error(`Usage: ${getMode() === "local" ? "./shannon" : "npx @keygraph/shannon"} logs <workspace>`);
			process.exit(1);
		}
		logs(workspaceId);
		break;
	}
	case "workspaces":
		workspaces(getVersion());
		break;
	case "status":
		status();
		break;
	case "setup":
		if (getMode() === "local") {
			console.error("ERROR: setup is only available in npx mode. In local mode, use .env");
			process.exit(1);
		}
		setup();
		break;
	case "build":
		build(args.includes("--no-cache"));
		break;
	case "uninstall":
		if (getMode() === "local") {
			console.error("ERROR: uninstall is only available in npx mode.");
			process.exit(1);
		}
		uninstall(args.includes("--yes") || args.includes("-y"));
		break;
	case "version":
	case "--version":
	case "-v":
		console.log(getVersionLine());
		break;
	case "help":
	case "--help":
	case "-h":
	case void 0:
		showHelp();
		break;
	default:
		console.error(`Unknown command: ${command}`);
		showHelp();
		process.exit(1);
}
